package edu.bvb.campus;

import org.springframework.web.bind.annotation.*;
import org.springframework.http.*;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.context.annotation.*;
import org.springframework.boot.CommandLineRunner;
import java.util.*;

@RestController @RequestMapping("/api")
class ApiController {
 final EngineService service; final UserRepo users; final TechRepo techs; final CategoryRepo categories; final SubcategoryRepo subs; final RequestRepo requests; final EventRepo events; final AssignmentRepo assignments;
 ApiController(EngineService s,UserRepo u,TechRepo t,CategoryRepo c,SubcategoryRepo sc,RequestRepo r,EventRepo e,AssignmentRepo a){service=s;users=u;techs=t;categories=c;subs=sc;requests=r;events=e;assignments=a;}
 AppUser actor(String h){return service.principal(h!=null&&h.startsWith("Bearer ")?h.substring(7):null);}
 Map<String,Object> user(AppUser u){return Map.of("id",u.id,"username",u.username,"name",u.displayName,"role",u.role);}
 Map<String,Object> req(ServiceRequest r){var m=new LinkedHashMap<String,Object>();m.put("id",r.id);m.put("title",r.title);m.put("description",r.description);m.put("location",r.location);m.put("category",r.category.name);m.put("categoryId",r.category.id);m.put("subcategory",r.subcategory.name);m.put("subcategoryId",r.subcategory.id);m.put("priority",r.priority);m.put("status",r.status);m.put("requester",r.requester.displayName);m.put("requesterId",r.requester.id);m.put("createdAt",r.createdAt);assignments.findByRequestId(r.id).ifPresent(a->{m.put("technician",a.technician.displayName);m.put("technicianId",a.technician.id);});return m;}
 @PostMapping("/auth/login") Map<String,Object> login(@RequestBody LoginInput in){AppUser u=service.login(in.username(),in.password());return Map.of("token",service.issue(u),"user",user(u));}
 @GetMapping("/me") Map<String,Object> me(@RequestHeader(value="Authorization",required=false)String h){return user(actor(h));}
 @GetMapping("/categories") List<Map<String,Object>> categoryList(){return categories.findByActiveTrue().stream().map(c->Map.<String,Object>of("id",c.id,"name",c.name,"subcategories",subs.findByActiveTrue().stream().filter(s->s.category.id.equals(c.id)).map(s->Map.<String,Object>of("id",s.id,"name",s.name,"skill",s.skill,"priority",s.defaultPriority)).toList())).toList();}
 @GetMapping("/requests") List<Map<String,Object>> list(@RequestHeader(value="Authorization",required=false)String h){return service.visibleRequests(actor(h)).stream().map(this::req).toList();}
 @PostMapping("/requests") ResponseEntity<?> create(@RequestHeader(value="Authorization",required=false)String h,@RequestBody RequestInput in){return ResponseEntity.status(201).body(req(service.submit(actor(h),in)));}
 @GetMapping("/requests/{id}") Map<String,Object> one(@RequestHeader(value="Authorization",required=false)String h,@PathVariable long id){AppUser a=actor(h);ServiceRequest r=requests.findById(id).orElseThrow();if(a.role!=Role.ADMIN&&a.role==Role.REQUESTER&&!r.requester.id.equals(a.id))throw new RuntimeException("Access denied");if(a.role==Role.TECHNICIAN&&!assignments.findByRequestId(id).map(x->x.technician.id.equals(a.id)).orElse(false))throw new RuntimeException("Access denied");return req(r);}
 @GetMapping("/requests/{id}/events") List<Map<String,Object>> history(@RequestHeader(value="Authorization",required=false)String h,@PathVariable long id){one(h,id);return events.findByRequestIdOrderByCreatedAtAsc(id).stream().map(e->Map.<String,Object>of("id",e.id,"from",e.fromStatus==null?"":e.fromStatus,"to",e.toStatus,"note",e.note==null?"":e.note,"actor",e.actor.displayName,"createdAt",e.createdAt)).toList();}
 @PostMapping("/requests/{id}/assign") Map<String,Object> assign(@RequestHeader(value="Authorization",required=false)String h,@PathVariable long id){ServiceAssignment a=service.allocate(id,actor(h));if(a==null)return Map.of("queued",true,"message","No eligible technician is available. Request remains queued.");return Map.of("request",req(a.request),"technician",a.technician.displayName);}
 @PatchMapping("/requests/{id}/status") Map<String,Object> status(@RequestHeader(value="Authorization",required=false)String h,@PathVariable long id,@RequestBody StatusInput in){return req(service.changeStatus(id,in.status(),in.note(),actor(h)));}
 @GetMapping("/queue") List<Map<String,Object>> queue(@RequestHeader(value="Authorization",required=false)String h){service.require(actor(h),Role.ADMIN);return requests.findAllByOrderByCreatedAtDesc().stream().filter(r->r.status==RequestStatus.QUEUED||r.status==RequestStatus.SUBMITTED).sorted(Comparator.comparingInt((ServiceRequest r)->r.priority==Priority.HIGH?0:r.priority==Priority.MEDIUM?1:2).thenComparing(r->r.createdAt).thenComparing(r->r.id)).map(this::req).toList();}
 @GetMapping("/admin/overview") Map<String,Object> overview(@RequestHeader(value="Authorization",required=false)String h){service.require(actor(h),Role.ADMIN);var all=requests.findAll();return Map.of("total",all.size(),"open",all.stream().filter(r->r.status!=RequestStatus.COMPLETED&&r.status!=RequestStatus.CANCELLED).count(),"completed",all.stream().filter(r->r.status==RequestStatus.COMPLETED).count(),"queued",all.stream().filter(r->r.status==RequestStatus.QUEUED).count(),"technicians",users.findByRole(Role.TECHNICIAN).size());}
 @GetMapping("/admin/accounts") List<Map<String,Object>> accounts(@RequestHeader(value="Authorization",required=false)String h){service.require(actor(h),Role.ADMIN);return users.findAll().stream().map(u->Map.<String,Object>of("id",u.id,"username",u.username,"name",u.displayName,"role",u.role,"enabled",u.enabled)).toList();}
 @GetMapping("/admin/technicians") List<Map<String,Object>> technicians(@RequestHeader(value="Authorization",required=false)String h){service.require(actor(h),Role.ADMIN);return users.findByRole(Role.TECHNICIAN).stream().map(u->{var p=techs.findById(u.id).orElse(new TechnicianProfile(u.id,"",""));return Map.<String,Object>of("id",u.id,"username",u.username,"name",u.displayName,"enabled",u.enabled,"available",p.available,"skills",p.skills,"locations",p.locations,"activeWorkload",assignments.countByTechnicianIdAndRequestStatusIn(u.id,List.of(RequestStatus.ASSIGNED,RequestStatus.ACCEPTED,RequestStatus.IN_PROGRESS)),"maxActive",p.maxActive);}).toList();}
 @PostMapping("/admin/technicians") Map<String,Object> addTech(@RequestHeader(value="Authorization",required=false)String h,@RequestBody Map<String,String> in){service.require(actor(h),Role.ADMIN);AppUser u=users.save(new AppUser(in.get("username"),in.get("name"),service.encoder.encode(in.get("password")),Role.TECHNICIAN));var p=new TechnicianProfile(u.id,in.getOrDefault("skills","General"),in.getOrDefault("locations","Main Block"));p.available=true;techs.save(p);return user(u);}
 @PostMapping("/admin/technicians/{id}/reset-password") Map<String,Object> reset(@RequestHeader(value="Authorization",required=false)String h,@PathVariable long id,@RequestBody ResetInput in){service.require(actor(h),Role.ADMIN);if(in.password()==null||in.password().length()<8)throw new RuntimeException("Use at least 8 characters");AppUser u=users.findById(id).orElseThrow();if(u.role!=Role.TECHNICIAN)throw new RuntimeException("Technician account not found");u.passwordHash=service.encoder.encode(in.password());users.save(u);return Map.of("updated",true,"message","Password reset. The new password is not retrievable.");}
 @PatchMapping("/admin/technicians/{id}") Map<String,Object> updateTech(@RequestHeader(value="Authorization",required=false)String h,@PathVariable long id,@RequestBody Map<String,Object> in){service.require(actor(h),Role.ADMIN);AppUser u=users.findById(id).orElseThrow();var p=techs.findById(id).orElseThrow();if(in.containsKey("enabled"))u.enabled=(boolean)in.get("enabled");if(in.containsKey("available"))p.available=(boolean)in.get("available");if(in.containsKey("maxActive"))p.maxActive=((Number)in.get("maxActive")).intValue();if(in.containsKey("skills")){p.skills.clear();p.skills.addAll(Arrays.asList(((String)in.get("skills")).split(",")));}if(in.containsKey("locations")){p.locations.clear();p.locations.addAll(Arrays.asList(((String)in.get("locations")).split(",")));}users.save(u);techs.save(p);return user(u);}
 @PostMapping("/admin/categories") Map<String,Object> addCategory(@RequestHeader(value="Authorization",required=false)String h,@RequestBody Map<String,String> in){service.require(actor(h),Role.ADMIN);var c=categories.save(new ServiceCategory(in.get("name")));return Map.of("id",c.id,"name",c.name);}
 @PostMapping("/admin/categories/{id}/subcategories") Map<String,Object> addSub(@RequestHeader(value="Authorization",required=false)String h,@PathVariable long id,@RequestBody Map<String,String> in){service.require(actor(h),Role.ADMIN);var s=subs.save(new ServiceSubcategory(in.get("name"),categories.findById(id).orElseThrow(),in.get("skill"),Priority.valueOf(in.getOrDefault("priority","MEDIUM"))));return Map.of("id",s.id,"name",s.name);}
 @PatchMapping("/admin/subcategories/{id}") Map<String,Object> editSub(@RequestHeader(value="Authorization",required=false)String h,@PathVariable long id,@RequestBody Map<String,Object> in){service.require(actor(h),Role.ADMIN);var s=subs.findById(id).orElseThrow();if(in.containsKey("name"))s.name=(String)in.get("name");if(in.containsKey("skill"))s.skill=(String)in.get("skill");if(in.containsKey("priority"))s.defaultPriority=Priority.valueOf((String)in.get("priority"));if(in.containsKey("active"))s.active=(boolean)in.get("active");subs.save(s);return Map.of("id",s.id,"name",s.name,"priority",s.defaultPriority,"active",s.active);}
}

@RestControllerAdvice class ApiErrors { @ExceptionHandler(RuntimeException.class) ResponseEntity<Map<String,String>> error(RuntimeException ex){String m=ex.getMessage()==null?"Request failed":ex.getMessage();return ResponseEntity.status(m.equals("Access denied")?403:m.equals("Sign in required")?401:400).body(Map.of("error",m));} }
@Configuration class WebConfig { @Bean org.springframework.security.web.SecurityFilterChain filterChain(HttpSecurity h)throws Exception{return h.csrf(c->c.disable()).authorizeHttpRequests(a->a.anyRequest().permitAll()).build();} @Bean CommandLineRunner seed(EngineService service){return args->service.seed();} }
